import{_ as e,o as i,c as o,ae as l}from"./chunks/framework.qNV68s4p.js";const p=JSON.parse('{"title":"平台支持","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/platform-support.md","filePath":"zh/guide/platform-support.md","lastUpdated":1776335312000}'),r={name:"zh/guide/platform-support.md"};function t(d,a,n,s,h,c){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="平台支持" tabindex="-1">平台支持 <a class="header-anchor" href="#平台支持" aria-label="Permalink to &quot;平台支持&quot;">​</a></h1><p>SweetEditor 面向多个 Compose Multiplatform 平台。</p><h2 id="支持的目标平台" tabindex="-1">支持的目标平台 <a class="header-anchor" href="#支持的目标平台" aria-label="Permalink to &quot;支持的目标平台&quot;">​</a></h2><ul><li>Android</li><li>iOS</li><li>JVM Desktop</li><li>JS</li><li>Wasm</li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><ul><li><code>commonMain</code>: 共享 API、编辑器模型、协议解码、控制器逻辑</li><li><code>androidMain</code>: Android 平台桥接</li><li><code>iosMain</code>: iOS 平台桥接</li><li><code>jvmMain</code>: Desktop/JVM 平台桥接</li><li><code>webMain</code>: Web 平台相关代码</li></ul><h2 id="平台说明" tabindex="-1">平台说明 <a class="header-anchor" href="#平台说明" aria-label="Permalink to &quot;平台说明&quot;">​</a></h2><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ul><li>IME 和文本输入通过 Android 平台钩子集成</li><li>Compose UI 承载编辑器，并将手势桥接到原生编辑器输入模型</li></ul><h3 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h3><ul><li>iOS bridge 代码位于独立的 iOS source set</li><li>原生生命周期和渲染协调由 Kotlin wrapper 层负责</li></ul><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><ul><li>支持鼠标、滚轮、键盘、popup 和 inline suggestion 交互</li><li>Desktop 的滚轮归一化在平台层单独处理</li></ul><h3 id="web-wasm" tabindex="-1">Web / Wasm <a class="header-anchor" href="#web-wasm" aria-label="Permalink to &quot;Web / Wasm&quot;">​</a></h3><ul><li>作为 wrapper 层的目标平台输出之一</li><li>某些平台交互能力会随着运行环境继续迭代</li></ul><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><p>尽量将共享编辑器逻辑放在 <code>commonMain</code>，并把平台特定行为隔离在对应 source set 中。</p>',17)])])}const m=e(r,[["render",t]]);export{p as __pageData,m as default};
